}

// HOME
function Home({ state, updateState, nav }) {
  const { cookie_consent_given } = state;
  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-4">Home</h1>

      {cookie_consent_given === null && (
        <button id="cookie-accept" className="bg-blue-600 text-white px-4 py-2 rounded mb-4 block"
                onClick={() => updateState({ cookie_consent_given: true })}>
          Accept Cookies
        </button>
      )}

      {cookie_consent_given === true && (
        <div className="space-y-4">
          <button id="nav-workspaces" className="bg-gray-100 px-4 py-2 border rounded block hover:bg-gray-200"
                  onClick={() => nav('WORKSPACE_LIST')}>
            Go to Workspaces (Direct)
          </button>

          <div id="top-nav-workspaces" className="group relative bg-gray-100 px-4 py-2 border rounded w-fit cursor-pointer hover:bg-gray-200">
            Hover for Workspaces
            <div className="hidden group-hover:block absolute top-full left-0 bg-white border shadow mt-1 p-2 space-y-2 z-10 w-48">
              <button className="menu-all-workspaces block w-full text-left px-4 py-2 hover:bg-gray-100"
                      onClick={() => nav('WORKSPACE_LIST')}>
                All Workspaces
              </button>
              <button className="menu-recent block w-full text-left px-4 py-2 hover:bg-gray-100"
                      onClick={() => nav('WORKSPACE_LIST')}>
                Recent
              </button>
            </div>
          </div>

          <button id="nav-profile" className="bg-gray-100 px-4 py-2 border rounded block hover:bg-gray-200"
                  onClick={() => nav('PROFILE_SETTINGS')}>
            Profile Settings
          </button>
        </div>
      )}
    </div>
  );
}

function WorkspaceList({ state, updateState, nav }) {
  const { location_permission_granted, workspace_list_filters_applied, workspace_list_has_searched, workspace_list_viewport_anchor_id, matched_team_id, teams } = state;

  return (
    <div className="flex flex-col h-full h-[600px]">
      <div className="p-4 border-b">
        <h2 className="text-xl font-semibold">Workspaces</h2>
        <button id="back-home" onClick={() => nav('HOME')} className="text-sm text-blue-600 mb-2 mt-2 inline-block hover:underline">
          &larr; Back to Home
        </button>

        {location_permission_granted === null && (
          <div className="bg-yellow-100 p-2 my-2 rounded flex justify-between items-center text-sm">
            <span>Allow location access for nearby workspaces?</span>
            <button id="permission-location-allow" onClick={() => updateState({ location_permission_granted: true })} className="bg-yellow-200 px-2 py-1 rounded">Allow</button>
          </div>
        )}

        <div className="flex gap-2 mb-2 mt-2 items-center">
          <input id="workspace-filter-text" type="text" placeholder="Filter workspaces..." className="border p-1 rounded text-sm flex-1"
                 onChange={(e) => {}} />
          <button id="workspace-filter-include-joined" onClick={() => updateState({ workspace_list_filters_applied: true })} className="bg-blue-100 px-2 py-1 rounded text-sm">
            Apply Filter
          </button>
        </div>

        <div className="flex gap-2 items-center">
          <input id="workspace-search-input" type="text" placeholder="Search..." className="border p-1 rounded text-sm flex-1"
                 onKeyDown={(e) => {
                   if (e.key === 'Enter' && e.target.value) {
                     updateState({ matched_team_id: 'team_1', workspace_list_has_searched: true });
                   }
                 }} />
        </div>
      </div>

      <div id="workspace-list-container" className="flex-1 overflow-y-auto p-4 cursor-ns-resize"
           onClick={() => updateState({ workspace_list_viewport_anchor_id: 'team_1' })}>
        <p className="text-xs text-gray-500 mb-2">Drag down to scroll into view</p>
        <div id="workspace-list" className="space-y-2">

          {workspace_list_filters_applied && (
             <div className="workspace-row-filtered p-3 border rounded hover:bg-gray-50 cursor-pointer flex justify-between items-center"
                  onClick={() => {
                    updateState({ workspace_list_filters_applied: null, selected_team_id: 'team_1' });
                    nav('CHANNEL_LIST');
                  }}>
               <span className="font-medium">Engineering (Filtered)</span>
             </div>
          )}

          {matched_team_id && workspace_list_has_searched && (
             <div className="workspace-row-matched p-3 border border-blue-300 bg-blue-50 rounded hover:bg-blue-100 cursor-pointer flex justify-between items-center"
                  onClick={() => {
                    updateState({ workspace_list_has_searched: null, selected_team_id: matched_team_id });
                    nav('CHANNEL_LIST');
                  }}>
               <span className="font-medium">Engineering (Matched)</span>
             </div>
          )}

          {workspace_list_viewport_anchor_id && (
             <div className="workspace-row-visible p-3 border border-green-300 bg-green-50 rounded hover:bg-green-100 cursor-pointer flex justify-between items-center"
                  onClick={() => {
                    updateState({ workspace_list_viewport_anchor_id: null, selected_team_id: workspace_list_viewport_anchor_id });
                    nav('CHANNEL_LIST');
                  }}>
               <span className="font-medium">Engineering (Visible)</span>
             </div>
          )}

          {!workspace_list_filters_applied && !workspace_list_has_searched && !workspace_list_viewport_anchor_id && teams.map(t => (
            <div key={t.id} className="p-3 border rounded opacity-50">
              <span className="font-medium">{t.name}</span> <span className="text-xs text-gray-400 ml-2">(Use actions above to open)</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

