          <label className="block text-sm font-semibold mb-1">What I do (Title)</label>
          <input id="profile-title-input" type="text" className="w-full border p-2 rounded"
                 onChange={(e) => updateState({ profile_title: e.target.value })} value={profile_title || ''} />
        </div>

        <div>
          <label className="block text-sm font-semibold mb-1">Timezone</label>
          <div className="group relative w-full">
            <button id="profile-timezone-dropdown" className="border px-4 py-2 w-full text-left bg-white rounded flex justify-between">
              Select Timezone <span className="text-xs">▼</span>
            </button>
            <div className="hidden group-hover:block absolute top-full left-0 w-full bg-white border mt-1 rounded shadow-lg z-10 max-h-40 overflow-y-auto">
              <div id="profile-timezone-utc" className="p-2 hover:bg-gray-100 cursor-pointer" onClick={() => updateState({ profile_timezone: 'UTC' })}>UTC</div>
              <div id="profile-timezone-pst" className="p-2 hover:bg-gray-100 cursor-pointer" onClick={() => updateState({ profile_timezone: 'PST' })}>PST</div>
              <div id="profile-timezone-est" className="p-2 hover:bg-gray-100 cursor-pointer" onClick={() => updateState({ profile_timezone: 'EST' })}>EST</div>
            </div>
          </div>
        </div>
      </div>

      <div className="pt-4 border-t mt-4 flex justify-end gap-2">
        <button onClick={() => nav('HOME')} className="px-4 py-2 rounded font-bold text-gray-600 hover:bg-gray-100 border">Cancel</button>
        <button id="profile-save-button"
                disabled={!profile_display_name || profile_display_name.length === 0}
                onClick={() => nav('UPDATE_PROFILE_SUCCESS')}
                className="bg-green-600 text-white px-6 py-2 rounded font-bold disabled:opacity-50">
          Save Changes
        </button>
      </div>
    </div>
  );
}

function UpdateProfileSuccess({ state, updateState, nav }) {
  return (
    <div className="p-6 text-center mt-20">
      <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4 text-2xl">✓</div>
      <h2 className="text-2xl font-bold mb-6">Profile Updated!</h2>
      <div className="flex justify-center gap-4">
        <button id="go-home" onClick={() => {
          updateState({ profile_updated: true });
          nav('HOME');
        }} className="bg-gray-200 px-4 py-2 rounded">Go to Home</button>
        <button id="back-profile" onClick={() => nav('PROFILE_SETTINGS')} className="bg-indigo-600 text-white px-4 py-2 rounded">Back to Profile</button>
      </div>
    </div>
  );
}

